     "visual": {
      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">WISDOM</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">On Seneca's retirement</text><rect x=\"80\" y=\"280\" width=\"940\" height=\"380\" rx=\"20\" fill=\"rgba(139,92,246,0.1)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"370\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"28\">\"I withdrew not only from people,</text><text x=\"550\" y=\"420\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"28\">but from public business.</text><text x=\"550\" y=\"490\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"28\">Above all, I withdrew</text><text x=\"550\" y=\"540\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"28\">from my own self.\"</text><text x=\"900\" y=\"620\" text-anchor=\"end\" fill=\"#8b5cf6\" font-size=\"22\">— Seneca, Letter 8</text><rect x=\"200\" y=\"740\" width=\"700\" height=\"100\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"785\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">The deepest withdrawal is</text><text x=\"550\" y=\"815\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">from your own distracted self.</text></svg>",
      "caption": "On withdrawal"
     }
