" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"760\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">Train one. Stop chasing</text><text x=\"550\" y=\"800\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">the other.</text></svg>",
