" stroke=\"#888\" stroke-width=\"2\" stroke-dasharray=\"6\"/><line x1=\"720\" y1=\"345\" x2=\"600\" y2=\"425\" stroke=\"#888\" stroke-width=\"2\" stroke-dasharray=\"6\"/><line x1=\"835\" y1=\"400\" x2=\"625\" y2=\"495\" stroke=\"#888\" stroke-width=\"2\" stroke-dasharray=\"6\"/><rect x=\"100\" y=\"640\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"700\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">CHARACTER CONTAGION</text><text x=\"550\" y=\"755\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Your closest five = your baseline</text><text x=\"550\" y=\"795\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">They mirror you back to yourself</text><rect x=\"200\" y=\"870\" width=\"700\" height=\"100\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"915\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">Pick the mirrors deliberately.</text><text x=\"550\" y=\"950\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">They are forming you.</text></svg>",
